"""Layer 15 MLP down_proj, component 3976.

It responds to words that introduce a specific instance or emphasise one ("especially",
"particularly", "notably", "in particular", "including", "for example", "for instance", and
their translations). It is largest on those words and somewhat raised for the next few
tokens; everywhere else it sits near its mean value (about -0.02), with a large spread that
no word- or context-level rule explains.
"""

READS = ()

MEAN = -0.02
STRONG = {"especially": 1.2, "particularly": 1.0, "notably": 0.8, "surtout": 1.2,
          "notamment": 1.4, "especialmente": 1.4, "особенно": 1.2, "特别是": 1.3,
          "尤其": 1.8, "尤其是": 1.6, "特に": 1.2, "特別是": 1.3}
WEAK = {"particular": 0.5, "including": 0.4, "example": 0.15, "instance": 0.05}
WINDOW = 3  # tokens after a trigger word that get a raised value
WINDOW_VALUE = 0.2


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    words = [_word(s) for s in prefix.token_strings[-(WINDOW + 2):]]
    word = words[-1]
    if word in STRONG:
        return carry, float(STRONG[word])
    if word in WEAK:
        return carry, float(WEAK[word])
    # the last few tokens before this one: a trigger there raises this position
    for back in range(2, WINDOW + 2):
        if len(words) >= back and (words[-back] in STRONG or words[-back] in WEAK):
            return carry, WINDOW_VALUE
    return carry, MEAN

"""Layer 15 MLP down-projection, component 3982: a word-level sketch.

What it does, in plain terms: this component adds a small signed amount to the residual
stream at each token. Most of its size is not predictable from the words around it, so this
program only captures three word classes that do shift its average value:

* Acceptability judgments such as "fine", "good", "correct", "okay", "agree", "works",
  "understand". They are clearly positive when used as a predicate after "is", "was",
  "works", "seems", "it's", "all" ("it's all fine", "works fine", "is correct").
  Elsewhere (e.g. "fine art", "fine-tuning") they are only slightly positive.
* Quantity-of-change words such as "same", "difference(s)", "change(s)", "nothing", "all":
  weakly positive.
* Concessive "but", "though", "although": negative.

All other tokens predict 0. The three classes together explain well under 1% of the
component's variance; the rest comes from context this program does not model.
"""

READS = ()

JUDGE = {
    "fine", "good", "great", "okay", "ok", "glad", "perfect", "correct", "correctly",
    "agree", "understand", "understood", "works", "easy",
}
BEFORE_PREDICATE = {
    "is", "was", "be", "are", "been", "being", "work", "works", "working", "seems",
    "seem", "s", "that", "it", "all", "this",
}
CHANGE_WORDS = {"same", "difference", "differences", "change", "changes", "nothing", "all"}
CONCESSIVE = {"but", "though", "although"}


def _word(token):
    return token.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    before = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = _word(prefix.token_strings[-2])
    if word in JUDGE:
        value = 0.43 if before in BEFORE_PREDICATE else 0.10
    elif word in CONCESSIVE:
        value = -0.15
    elif word in CHANGE_WORDS:
        value = 0.15
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP unit 3992 (component down_proj:3992), written as a readable rule.

In plain terms: this unit is a "next item of a pair or series" detector. It fires on the token
that starts the second half of a coordination, the word right after a link such as "and", "or",
"und", "et", "и", "&" or "+", or a dash, and most strongly on the second number of a numeric
range written with a dash ("10-12", "2019–20"), at the digit after the dash. Items in a
comma-separated list get a weaker push. Almost everywhere else it sits near zero, with small
positive values on digits and on math operators.

The numbers are typical sizes read off the data, not fitted parameters of a model. Most of the
variance is token-level noise the rule cannot see, so this is a coarse summary.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

WORD_LINKS = {"and", "or", "und", "et", "y", "и", "&", "和", "nor", "to", "&&", "||"}
SYMBOL_LINKS = {"+", "/", "×", "-", "–", "—"}
DASHES = {"-", "–", "—"}
OPERATORS = {"+", "-", "/", "*", "^", "__"}
FUNCTION_WORDS = set(
    "the a an of in on at to by for with from as is was are were be been it its this that these "
    "those he she they we you i his her their our and or but if then so not there when which who "
    "will can may has have had do does".split()
)


def is_digit(s: str) -> bool:
    return len(s) == 1 and s.isdigit()


def kind(s: str) -> str:
    """The sort of token: digit, blank, function word, punctuation, capitalised or plain word."""
    if s == "":
        return "blank"
    if s.isdigit():
        return "digit"
    if s.lower() in FUNCTION_WORDS:
        return "function"
    if not any(c.isalnum() for c in s):
        return "punct"
    return "capitalised" if s[0].isupper() else "word"


def step(carry, prefix, upstream: Mapping):
    strings = [s.strip() for s in prefix.token_strings]
    docs = prefix.document_ids
    back = []  # the three tokens before this one, blank across a document boundary
    for k in range(1, 4):
        same_doc = len(strings) > k and docs[-k - 1] == docs[-1]
        back.append(strings[-k - 1] if same_doc else "")
    prev, prev2, _ = back
    cur = strings[-1]
    what = kind(cur)
    if prev == "" and prev2:  # a bare space between a link and the next item: look past it
        prev, prev2 = prev2, ""
    if is_digit(cur) and prev in DASHES and is_digit(prev2):
        return carry, 4.1  # second number of a range, 10-12 or 2019–20
    if is_digit(cur) and prev in DASHES:
        return carry, 0.6
    if prev in WORD_LINKS:
        return carry, {"digit": 0.2, "capitalised": 2.1, "blank": 2.7}.get(what, 1.1)
    if prev in SYMBOL_LINKS:
        return carry, {"digit": 1.3, "blank": 1.2}.get(what, 0.7)
    if prev == ",":
        return carry, {"digit": 0.9, "blank": 1.0, "capitalised": 0.55}.get(what, 0.35)
    if prev2 in WORD_LINKS | SYMBOL_LINKS:
        return carry, 0.3  # two tokens after a link: the item is still being coordinated
    if is_digit(cur):
        return carry, 0.33
    if cur in OPERATORS:
        return carry, 1.0
    if cur in {"and", "or"}:
        return carry, -0.4
    if cur in {",", "=", "with", "than"}:
        return carry, -0.2
    return carry, 0.08

"""Year digits: the component goes negative while a year is being written.

What it responds to, in plain terms:
- the second digit of a number starting with 1 or 2, by what the digits so far are:
  "19" (1900s) is most negative, then "20" (2000s), then "18"; other 1x/2x are near zero;
- the third digit of a year already begun with "19" or "20" (strongly for 200-202);
- a bare space that comes just before a number: negative after a month name or a
  date word ("in", "from", ...), mildly negative after a comma, slightly otherwise.

All these values are stronger in a date context (a month name or date word a few tokens
back), and near zero everywhere else. The program reads only the tokens so far.
The numbers are rough group averages fitted on training text, not exact values.
"""

import calendar

READS = ()

MONTHS = {name for name in calendar.month_name[1:] + calendar.month_abbr[1:] if name}
DATE_WORDS = MONTHS | {"in", "from", "since", "during", "until", "on"}

# activation at the second digit, given the digits typed so far
SECOND_DIGIT = {"19": -3.8, "20": -3.2, "18": -1.9}
DATE_BOOST = 2.3  # the same digits in a date context are about this many times stronger


def is_digit(token):
    return len(token) == 1 and token.isdigit()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    token = tokens[-1]

    # a bare space: does it come right after a date word or a comma?
    if token == " ":
        before = tokens[-2].strip() if len(tokens) > 1 else ""
        if before in DATE_WORDS:
            return carry, -2.5
        return carry, -1.35 if before == "," else -0.3

    if not is_digit(token):
        return carry, 0.0

    # the digits of the number being typed, from its first digit to this one
    start = len(tokens) - 1
    while start > 0 and is_digit(tokens[start - 1]):
        start -= 1
    digits = "".join(tokens[start:])
    if start == 0 or digits[0] not in "12" or len(digits) > 3:
        return carry, 0.0

    # a date context: a month name or date word in the few tokens before the number
    before = [w.strip() for w in tokens[max(0, start - 5) : start - 1]]
    boost = DATE_BOOST if any(w in DATE_WORDS for w in before) else 1.0

    if len(digits) == 2:
        value = SECOND_DIGIT.get(digits, -1.4 if boost > 1 else -0.1)
    elif digits[:2] == "19":
        value = -1.7
    elif digits[:2] == "20" and digits[2] in "012":
        value = -4.5
    else:
        value = 0.0
    return carry, value * boost

"""Layer 15 MLP down_proj, component 4009.

What it does: a mostly quiet feature that turns negative inside noun phrases that name a
setting, sector, field or general category. Its strongest negative values fall on
  - modifiers that open such a phrase: sector and domain adjectives ("entire", "whole",
    "financial", "economic", "medical", "digital", ...) and compass directions ("southern",
    "northern", "eastern", "western", "central"), which come before a region or sector noun;
  - general category nouns: "system", "industry", "family", "career", "pathway", "world", ...;
  - a determiner right after a locative or time preposition: "in the", "within the",
    "during the", "throughout the", "across the", "of the" (also "in this", "of our", ...).
Elsewhere it sits near zero. Each value is roughly the average activation of its class
(about -1.2, -0.85 and -0.8), so the program is a small word-class lookup. It reads only
the current token and the one before it, within the same document.
"""

READS = ()

DETERMINERS = {"the", "this", "that", "these", "those", "your", "our", "their", "his", "its", "my"}
PREPOSITIONS = {
    "in", "within", "during", "throughout", "across", "into", "through", "of", "on", "at",
    "for", "from", "about", "over",
}
FIELD_NOUNS = {
    "system", "systems", "industry", "family", "career", "pathway", "pathways", "signaling",
    "process", "structure", "health", "world", "sector", "market", "region", "area", "field",
    "network", "chain", "management", "environment", "government", "community", "economy",
    "culture", "country", "history", "pandemic", "ecosystem", "theory", "literature",
}
MODIFIERS = {
    "entire", "whole", "overall", "immune", "financial", "digital", "territorial", "modern",
    "global", "economic", "chemical", "medical", "professional", "military",
    "administrative", "international", "electronic", "circuit", "assembly",
    "southern", "northern", "eastern", "western", "central",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in MODIFIERS:
        return carry, -1.25
    if word in FIELD_NOUNS:
        return carry, -0.85
    if word in DETERMINERS and before in PREPOSITIONS:
        return carry, -0.8
    return carry, 0.0

"""Layer 15, MLP hidden unit 4024: the component p-82af68dd@100000/layers.15.mlp.down_proj:4024.

The component is one hidden unit of the layer-15 MLP (its down_proj direction is about
two-thirds aligned with that unit's own output direction), so its activation is that unit's
value, scaled. The unit's value depends on context in ways simple features do not capture:
the current token alone explains none of its variance, and neighbouring-token classes and
repeats explain only a little. The clear pattern is positional, plus a small effect of
whitespace-only tokens (indentation, a lone space):

- At a document's first token the unit is about zero.
- Over the next few tokens of a document it is negative: about -0.8 at positions 1 to 3,
  -0.5 at positions 4 to 7, -0.2 at positions 8 to 15, and about zero after that.
- A whitespace-only token pushes it down by 0.25, and so does a token that follows one.

This program predicts those values. On the eval rows it explains about 1 percent of the
variance; a lookup table of tokens and their neighbours would explain a few percent more, but
it would not be a readable explanation.
"""

READS = ()


def _is_space(s):
    """A token that is only spaces or tabs, with no newline."""
    return s != "" and s.strip() == "" and "\n" not in s


def _position_value(pos):
    if pos == 0:
        return 0.0
    if pos < 4:
        return -0.8
    if pos < 8:
        return -0.5
    if pos < 16:
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    # carry: (position in the document of the previous token, whether that token was whitespace)
    if carry is None or prefix.document_ids[-1] != prefix.document_ids[-2]:
        pos, prev_space = 0, False
    else:
        pos, prev_space = carry[0] + 1, carry[1]
    space = _is_space(prefix.token_strings[-1])
    value = _position_value(pos)
    if pos > 0:
        if space:
            value -= 0.25
        if prev_space:
            value -= 0.25
    return (pos, space), float(value)

"""Algebra-term detector for layer 15's MLP down-projection, component 4031.

What the component does: it writes into the residual stream mostly while the text is
algebra. It is strongest on a power term's superscript (the ² in x², the ³ in x³). It is
weaker on the exponent digit after ^ (x^2), and on the variables, digits and closing
brackets of a polynomial or equation. Its size grows with how many + and - signs the
recent text has (a sum of terms is being written) and with how much maths sits in the
last few tokens.

This program predicts the activation from the prefix alone, with three ingredients:
  signs  = 1 + number of + / - / − tokens in the last 64 tokens of the same document
  maths  = number of maths tokens (digits, single letters, operators, brackets) among
           the last 6 tokens of the same document
and then:
  ²  or ³                                 -> 5.3 + 1.05 * signs
  digit right after ^ or **               -> 1.85 * signs
  digit / letter / closing bracket        -> (0.08 / 0.15 / 0.19) * signs * maths
  anything else                           -> 0
Predicting the superscript and exponent terms carries most of what the component does.
"""

READS = ()

SIGNS = {"+", "-", "−"}
POWER_OPS = {"^", "**"}
DIGITS = set("0123456789")
CLOSERS = {")", "}", "]"}
MATH_SYMBOLS = {"^", "=", "+", "-", "−", "*", "/", "(", ")", "[", "]", "{", "}", "$", "\\", "²", "³"}
SIGN_WINDOW = 64
MATH_WINDOW = 6


def _is_letter(s):
    return len(s) == 1 and s.isascii() and s.isalpha()


def step(carry, prefix, upstream):
    n = len(prefix.token_strings)
    doc = prefix.document_ids[-1]
    lo = max(0, n - 1 - SIGN_WINDOW)
    # the tokens before the current one, within the same document
    before = [
        s.strip()
        for s, d in zip(prefix.token_strings[lo : n - 1], prefix.document_ids[lo : n - 1])
        if d == doc
    ]
    signs = 1 + sum(1 for s in before if s in SIGNS)
    maths = sum(
        1
        for s in before[-MATH_WINDOW:]
        if s in MATH_SYMBOLS or s in DIGITS or _is_letter(s)
    )
    token = prefix.token_strings[-1].strip()
    same_doc = n > 1 and prefix.document_ids[-2] == doc
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    if token in ("²", "³"):
        return carry, float(5.3 + 1.05 * signs)
    if token in DIGITS and prev in POWER_OPS:
        return carry, float(1.85 * signs)
    if token in DIGITS:
        weight = 0.08
    elif _is_letter(token):
        weight = 0.15
    elif token in CLOSERS:
        weight = 0.19
    else:
        weight = 0.0
    return carry, float(weight * signs * maths)
